// Package codegen turns a browse of an OPC UA server into the two committed
// files a manifest project consumes: opcua_manifest.yaml (the bindings)
// and tags/opcua.yaml (the tag file). It mirrors eip/codegen and
// modbus/codegen: deterministic, sorted, byte-identical on re-run, so a
// regenerated file diffs against the last one and shows what changed on the
// server rather than reshuffling.
package codegen

import (
	"fmt"
	"path"
	"sort"
	"strings"
	"unicode"

	"github.com/joyautomation/nautilus/internal/tagfile"
	"github.com/joyautomation/nautilus/opcua"
	"gopkg.in/yaml.v3"
)

// Options steer Generate.
type Options struct {
	// Patterns select variables by their GENERATED tag name (globs, any
	// match keeps); empty keeps everything scalar.
	Patterns []string
	// WritablePatterns mark bindings writable (globs on the tag name).
	// A variable the server marks read-only is never made writable.
	WritablePatterns []string
	// Prefix is prepended to every tag name ("GW_").
	Prefix string
	// Endpoint is named in the generated headers.
	Endpoint string
}

// Output is what Generate produced.
type Output struct {
	Manifest opcua.Manifest
	// Skipped explains every browsed variable that is NOT in the manifest,
	// one line each: not a scalar built-in, an array, filtered out.
	Skipped []string
}

// Generate maps browsed variables onto bindings. Tag names come from the
// browse path below the root, joined with "_" and sanitized to an
// identifier (letters, digits, underscore, not starting with a digit). A
// collision is an error, not a suffix: two nodes silently sharing a tag is
// the kind of mistake a review must see.
func Generate(br opcua.BrowseResult, opts Options) (Output, error) {
	var out Output
	out.Manifest.Namespaces = append([]string(nil), br.Namespaces...)
	byName := map[string]opcua.Variable{}
	for _, v := range br.Variables {
		name := opts.Prefix + TagName(v.Path)
		if !v.Scalar {
			out.Skipped = append(out.Skipped, fmt.Sprintf("%s: type %s is not a scalar built-in", name, v.Type))
			continue
		}
		if v.ValueRank >= 0 {
			out.Skipped = append(out.Skipped, fmt.Sprintf("%s: array (value rank %d)", name, v.ValueRank))
			continue
		}
		if !v.Readable {
			out.Skipped = append(out.Skipped, fmt.Sprintf("%s: not readable", name))
			continue
		}
		if len(opts.Patterns) > 0 && !matchesAny(name, opts.Patterns) {
			continue
		}
		if prev, dup := byName[name]; dup {
			return out, fmt.Errorf("tag name %s is generated for both %s and %s — narrow --root or use --prefix per import", name, prev.NodeID, v.NodeID)
		}
		byName[name] = v
		desc := v.Description
		if desc == "" || desc == v.DisplayName {
			desc = v.DisplayName
		}
		out.Manifest.Tags = append(out.Manifest.Tags, opcua.TagBinding{
			Name:      name,
			NodeID:    v.NodeID,
			Namespace: v.Namespace,
			Type:      v.Type,
			Writable:  v.Writable && matchesAny(name, opts.WritablePatterns),
			Desc:      desc,
		})
	}
	out.Manifest = out.Manifest.Sorted()
	sort.Strings(out.Skipped)
	return out, nil
}

// TagName derives a nautilus identifier from a browse path.
func TagName(path []string) string {
	var b strings.Builder
	for i, seg := range path {
		if i > 0 {
			b.WriteByte('_')
		}
		for _, r := range seg {
			switch {
			case unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_':
				b.WriteRune(r)
			default:
				b.WriteByte('_')
			}
		}
	}
	s := strings.Trim(b.String(), "_")
	for strings.Contains(s, "__") {
		s = strings.ReplaceAll(s, "__", "_")
	}
	if s == "" {
		return "_"
	}
	if unicode.IsDigit(rune(s[0])) {
		s = "_" + s
	}
	return s
}

func matchesAny(name string, pats []string) bool {
	for _, p := range pats {
		if ok, _ := path.Match(p, name); ok {
			return true
		}
	}
	return false
}

// ManifestYAML renders the manifest with a provenance header, bindings
// sorted by name. command is the import invocation to repeat.
func ManifestYAML(m opcua.Manifest, command string) ([]byte, error) {
	raw, err := yaml.Marshal(m.Sorted())
	if err != nil {
		return nil, err
	}
	header := fmt.Sprintf("# Generated by `%s` — the server's variables as tag bindings.\n"+
		"# Do not edit; re-run the import to refresh. Namespace URIs are resolved\n"+
		"# against the live server at connect, so a renumbering is survived.\n", command)
	return append([]byte(header), raw...), nil
}

// TagsYAML renders the tag file: every binding as an input (or output when
// writable), with the browsed description.
func TagsYAML(m opcua.Manifest, command string, onlineTag string, skip []string) ([]byte, error) {
	header := []string{
		fmt.Sprintf("Generated by `%s` from the server's address space.", command),
		"Do not edit — re-run the import, or `naut opcua tags opcua_manifest.yaml`",
		"to re-derive this file from the committed manifest (no server needed).",
		"",
		"Compose it into a project with:  tag-files: [tags/opcua.yaml]",
	}
	if len(skip) > 0 {
		header = append(header, "", "Not generated (declared by hand in the project): "+strings.Join(skip, ", "))
	}
	var out []tagfile.Tag
	skipped := 0
	for _, t := range m.Tags {
		if matchesAny(t.Name, skip) {
			skipped++
			continue
		}
		tag := tagfile.Tag{Name: t.Name, Role: "input", Desc: t.Desc}
		if t.Writable {
			tag.Role = "output"
		}
		out = append(out, tag)
	}
	if onlineTag != "" && !matchesAny(onlineTag, skip) {
		out = append(out, tagfile.Tag{Name: onlineTag, Role: "input", Desc: "true while the OPC UA session is up (driver companion)"})
	}
	if len(skip) > 0 && skipped == 0 {
		return nil, fmt.Errorf("no binding matches any of the skip patterns (%s) — "+
			"a stale exclusion would silently regenerate a tag you declare by hand", strings.Join(skip, ", "))
	}
	return tagfile.Render(header, out)
}
